  prTitle: 'Elige un plan. Cámbialo cuando quieras.',
  prLede: 'Empieza en Free y quédate ahí si basta. Paga cuando quieras más canales, más créditos de IA o aprobaciones para tu equipo. El pago anual sale dos meses más barato.',
  prMetaDesc: 'Un plan gratuito que sigue siendo gratis, Solo para creadores, Team para aprobaciones, Business para escala, con 3, 6, 25 y 100 canales. Mensual o anual, y el anual te da dos meses gratis. Cancela cuando quieras.',
