  prChannels: 'Canales',
  prIntegrations: 'Integraciones',
  prEverythingIn: 'Todo lo de {plan}, más…',
  prStartFree: 'Empezar gratis',
  prChoose: 'Elegir {plan}',
  prFoot: 'Precios en USD. Los planes anuales se cobran una vez al año y dan dos meses gratis. Cancela cuando quieras, conservas tus datos.',
  prFaq1Q: '¿Qué cuenta para el límite de publicaciones programadas?',
  prFaq1A: 'Las publicaciones programadas o en espera de un canal que aún no se publicaron. El límite es por canal conectado, cada canal tiene su propia cuota, y un hueco se libera en cuanto se publica. Los borradores nunca cuentan.',
  prFaq2Q: '¿Cuántos canales puedo conectar?',
  prFaq2A: 'Free conecta 3, Solo 6, Team 25 y Business 100. Conectar Instagram cuesta lo mismo que conectar X, sin tarifas por canal.',
  prFaq3Q: '¿Cómo funcionan los créditos de IA?',
  prFaq3A: 'Cada plan recibe créditos de IA que se reinician el día 1 de cada mes: 20 en Free, luego 500, 1.500 y 5.000 en Solo, Team y Business. Una reescritura corta cuesta 1 crédito, un texto o adaptación 2, un hilo o reutilización 3 y un borrador largo 5.',
  prFaq4Q: '¿Puedo cambiar de plan o cancelar?',
  prFaq4A: 'En cualquier momento, desde los ajustes de facturación. Los cambios de plan o intervalo se aplican al momento y Stripe los prorratea; al cancelar mantienes el plan hasta el fin del periodo.',
  prFaq5Q: '¿Qué es la marca de agua de Sosial?',
  prFaq5A: 'Las publicaciones de Free llevan un pequeño sello “hecho con Sosial”. En Solo, Team y Business lo controlas tú y puedes apagarlo en el estudio; nunca afecta al contenido que traigas tú.',
  prFaq6Q: '¿Cobran por puestos en Team o Business?',
  prFaq6A: 'No. Team y Business son precios fijos para todo el espacio: hasta 5 miembros y 3 espacios en Team, miembros ilimitados y 6 espacios en Business.',
  prFaq7Q: '¿Cómo funciona el pago anual?',
  prFaq7A: 'Pagas una vez al año; el anual cuesta lo mismo que diez meses, así que son dos meses gratis. Los créditos de IA se reinician el día 1 de cada mes.',
