  prFaq3A: 'Chaque plan reçoit des crédits IA réinitialisés le 1er du mois : 20 sur Free, puis 500, 1 500 et 5 000 sur Solo, Team et Business. Une réécriture courte coûte 1 crédit, une légende ou adaptation 2, un fil ou recyclage 3, un long texte 5.',
  prFaq4Q: 'Puis-je changer de plan ou annuler ?',
  prFaq4A: 'À tout moment, depuis les réglages de facturation. Les changements s’appliquent immédiatement au prorata par Stripe ; en annulant, le plan tient jusqu’à la fin de la période.',
  prFaq5Q: 'Qu’est-ce que le filigrane Sosial ?',
  prFaq5A: 'Les posts Free portent un petit badge « réalisé avec Sosial ». Sur Solo, Team et Business vous le contrôlez et pouvez le désactiver dans le studio ; il ne s’applique jamais à votre propre contenu.',
  prFaq6Q: 'Facturez-vous les sièges sur Team ou Business ?',
  prFaq6A: 'Non. Team et Business sont des prix fixes pour tout l’espace : jusqu’à 5 membres et 3 espaces sur Team, membres illimités et 6 espaces sur Business.',
  prFaq7Q: 'Comment fonctionne la facturation annuelle ?',
  prFaq7A: 'Vous payez une fois par an ; l’annuel coûte le prix de dix mois, soit deux mois gratuits. Les crédits IA se réinitialisent toujours le 1er de chaque mois.',
