  prLede: 'Free로 시작하고 충분하면 그대로 두세요. 채널이 더 필요하거나 AI 크레딧, 팀 승인이 필요할 때 결제하세요. 연간 결제가 두 달 더 저렴합니다.',
  prMetaDesc: '무료로 유지되는 Free 플랜, 크리에이터용 Solo, 승인용 Team, 확장용 Business. 채널 3·6·25·100개. 월간 또는 연간, 연간은 두 달 무료. 언제든 해지 가능.',
