  prFoot: '가격은 USD. 연간 플랜은 1년에 한 번 청구되며 두 달 무료입니다. 언제든 해지 가능, 데이터는 유지됩니다.',
  prFaq1Q: '예약 게시물 한도에 무엇이 포함되나요?',
  prFaq1A: '예약되었거나 채널에서 대기 중이고 아직 게시되지 않은 게시물입니다. 한도는 연결된 채널별로 적용되며, 각 채널에 자체 배정이 있고 게시되면 바로 해제됩니다. 초안은 포함되지 않습니다.',
  prFaq2Q: '채널은 몇 개까지 연결할 수 있나요?',
  prFaq2A: 'Free는 3개, Solo 6개, Team 25개, Business 100개입니다. Instagram 연결이 X 연결과 비용이 같고 채널별 수수료가 없습니다.',
  prFaq3Q: 'AI 크레딧은 어떻게 작동하나요?',
  prFaq3A: '모든 플랜에 매월 1일 초기화되는 AI 크레딧이 제공됩니다: Free 20, Solo 500, Team 1,500, Business 5,000. 짧은 재작성은 1크레딧, 캡션이나 플랫폼 변환은 2, 스레드나 재활용은 3, 장문 초안은 5입니다.',
  prFaq4Q: '플랜을 바꾸거나 해지할 수 있나요?',
  prFaq4A: '언제든 결제 설정에서 가능합니다. 플랜과 결제 주기 변경은 즉시 적용되며 Stripe가 일할 계산합니다. 해지해도 기간 끝까지 플랜이 유지됩니다.',
  prFaq5Q: 'Sosial 워터마크란?',
  prFaq5A: 'Free 게시물에는 작은 “made with Sosial” 배지가 붙습니다. Solo, Team, Business에서는 직접 제어하고 스튜디오에서 끌 수 있으며, 직접 가져온 콘텐츠에는 적용되지 않습니다.',
  prFaq6Q: 'Team이나 Business에서 좌석 요금을 내나요?',
  prFaq6A: '아니요. Team과 Business는 워크스페이스 전체 정액제입니다. Team은 최대 5명·3개 워크스페이스, Business는 무제한 인원·6개 워크스페이스입니다.',
  prFaq7Q: '연간 결제는 어떻게 되나요?',
